import React from 'react';

function BirthdayService() {
  return (
    <div className="container py-4">
      <h2 className="text-center text-warning mb-4">Tổ chức sinh nhật & kỷ niệm</h2>
      <p>
        Dù là sinh nhật cho bé hay tiệc kỷ niệm cho người thân, chúng tôi đều có giải pháp trang trí và tổ chức phù hợp mọi độ tuổi và phong cách.
      </p>
      <ul>
        <li>Chủ đề hoạt hình, nhân vật nổi tiếng, fairy-tale,...</li>
        <li>Trang trí bóng bay, photobooth, bánh kem</li>
        <li>Hoạt náo viên, chú hề, ảo thuật gia</li>
        <li>Không gian gia đình hoặc nhà hàng</li>
      </ul>
    </div>
  );
}

export default BirthdayService;
